//! Geez inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Geez dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

/// Settings for systematic choices. `Geez::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Geez {
    pub options: Options,
}

impl Geez {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// The plural noun.
    pub fn noun_plural_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(0);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The plural noun. The best candidate; the word itself if nothing is known.
    pub fn noun_plural(&self, word: &str) -> String {
        best(self.noun_plural_scored(word), word)
    }

    /// A noun form (accusative).
    pub fn noun_accusative_scored(&self, word: &str, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (number,) {
            (Number::Singular,) => Some(1),
            (Number::Plural,) => Some(2),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form (accusative). The best candidate; the word itself if nothing is known.
    pub fn noun_accusative(&self, word: &str, number: Number) -> String {
        best(self.noun_accusative_scored(word, number), word)
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

}

/// The plural noun.
pub fn noun_plural(word: &str) -> String {
    Geez::default().noun_plural(word)
}

/// The plural noun. Every candidate with its confidence, best first.
pub fn noun_plural_scored(word: &str) -> Scored<String> {
    Geez::default().noun_plural_scored(word)
}

/// A noun form (accusative).
pub fn noun_accusative(word: &str, number: Number) -> String {
    Geez::default().noun_accusative(word, number)
}

/// A noun form (accusative). Every candidate with its confidence, best first.
pub fn noun_accusative_scored(word: &str, number: Number) -> Scored<String> {
    Geez::default().noun_accusative_scored(word, number)
}

/// Dictionary spelling of a noun.
pub fn noun_lemma(word: &str) -> String {
    Geez::default().noun_lemma(word)
}

/// One reading of a form: its part of speech, lemma, and every cell it fills
/// for that lemma (empty when it is only the dictionary form).
#[derive(Clone, Debug, PartialEq)]
pub struct Analysis {
    pub pos: &'static str,
    pub lemma: String,
    pub cells: Vec<&'static str>,
}

/// Which lemma and cell a form could be, best first. Works for unknown words too.
pub fn analyze(word: &str) -> Scored<Analysis> {
    let Some(m) = model() else { return Vec::new() };
    m.analyze(word)
        .into_iter()
        .filter_map(|(a, p)| {
            let pos = m.pos.get(a.pos)?;
            let cells = a.cells.iter().filter_map(|&c| pos.cells.get(c as usize).map(String::as_str)).collect();
            Some((Analysis { pos: pos.name.as_str(), lemma: a.lemma, cells }, p))
        })
        .collect()
}

/// Inflect by names, e.g. `inflect("noun", "GenitivePlural", word)`.
pub fn inflect(pos: &str, cell: &str, word: &str) -> Scored<String> {
    let Some(m) = model() else { return Vec::new() };
    let Some(pi) = m.pos.iter().position(|p| p.name == pos) else { return Vec::new() };
    let Some(ci) = m.pos.get(pi).and_then(|p| p.cells.iter().position(|c| c == cell)) else { return Vec::new() };
    m.inflect(pi, ci as u32, word, Options::default())
}
